#include <iostream>
#include <algorithm>
using namespace std;

int main() {
    int n, pos, l, r;
    cin >> n >> pos >> l >> r;

    int operations = 0;

    if (l > 1 && r < n) {
        if (pos < l) {
            operations = (l - pos) + 1 + (r - l) + 1;
        } else if (pos > r) {
            operations = (pos - r) + 1 + (r - l) + 1;
        } else {
            operations = min(pos - l, r - pos) + 1 + (r - l) + 1;
        }
    } else if (l > 1) {
        if (pos >= l) {
            operations = (pos - l) + 1;
        } else {
            operations = (l - pos) + 1;
        }
    } else if (r < n) {
        if (pos <= r) {
            operations = (r - pos) + 1;
        } else {
            operations = (pos - r) + 1;
        }
    } else {
        operations = 0;
    }

    cout << operations << endl;
    return 0;
}

